-- ============================================================================
-- SINCRONIZAR SECUENCIAS ANTES DE INSERTAR MONEDAS QUE PUEDAN FALTAR
-- Los INSERT originales de arriba cargan Id explicitos.
-- ============================================================================
DO $$
DECLARE
    secuencia_moneda TEXT;
    secuencia_pais TEXT;
    max_id_moneda BIGINT;
    max_id_pais BIGINT;
BEGIN
    secuencia_moneda := pg_get_serial_sequence('public.moneda', 'id');
    secuencia_pais := pg_get_serial_sequence('public.pais', 'id');

    SELECT COALESCE(MAX(Id), 0) INTO max_id_moneda FROM Moneda;
    SELECT COALESCE(MAX(Id), 0) INTO max_id_pais FROM Pais;

    IF secuencia_moneda IS NOT NULL THEN
        PERFORM setval(secuencia_moneda::regclass, GREATEST(max_id_moneda, 1), max_id_moneda > 0);
    END IF;
    IF secuencia_pais IS NOT NULL THEN
        PERFORM setval(secuencia_pais::regclass, GREATEST(max_id_pais, 1), max_id_pais > 0);
    END IF;
END $$;

-- ============================================================================
-- REQUISITOS OBLIGATORIOS DEL EXAMEN 4
-- 1. Validar si cada una de las cuatro monedas existe; insertarla si falta.
-- 2. Alimentar cambios diarios durante los ultimos dos meses.
-- 3. Si ya existe la combinacion moneda-fecha, actualizar el valor de Cambio.
--
-- Monedas seleccionadas: COP, EUR, GBP y BTC (Bitcoin).
-- Bitcoin se incorpora como cuarta moneda si aun no existe en Moneda.
-- No se registra en Pais porque es una criptomoneda descentralizada.
-- ============================================================================

-- 1. Validar existencia por Sigla e insertar unicamente las monedas faltantes.
-- La secuencia ya fue sincronizada con los Id explicitos de la carga historica.
SELECT datos.Sigla, datos.Moneda, datos.Simbolo, datos.Emisor
FROM (VALUES
    ('COP', 'Peso colombiano', '$', 'Colombia'),
    ('EUR', 'Euro', '€', 'Union Europea'),
    ('GBP', 'Libra esterlina', '£', 'Reino Unido'),
    ('BTC', 'Bitcoin', '₿', NULL)
) AS datos(Sigla, Moneda, Simbolo, Emisor)
WHERE NOT EXISTS (
    SELECT 1
    FROM Moneda AS existente
    WHERE existente.Sigla = datos.Sigla
)
ON CONFLICT (Sigla) DO NOTHING;

-- 2 y 3. Generar una fila por dia y moneda durante los dos ultimos meses.
-- Si ya existe (IdMoneda, Fecha), se actualiza Cambio mediante DO UPDATE.
-- Los valores son SINTETICOS y reproducibles: no son cotizaciones reales.
-- La moneda base/unidad de cotizacion no esta definida en el modelo del examen.
WITH monedas_objetivo AS (
    SELECT *
    FROM (VALUES
        ('COP', 3719.71::NUMERIC, 0.025::NUMERIC, 0),
        ('EUR', 0.86244070720138::NUMERIC, 0.015::NUMERIC, 3),
        ('GBP', 0.761527624414576::NUMERIC, 0.018::NUMERIC, 7),
        ('BTC', 95000.00::NUMERIC, 0.060::NUMERIC, 11)
    ) AS datos(Sigla, ValorBase, Variacion, Desfase)
), periodo AS (
    SELECT
        (CURRENT_DATE - INTERVAL '2 months')::DATE AS FechaInicio,
        CURRENT_DATE::DATE AS FechaFin
), fechas AS (
    SELECT
        serie.FechaHora::DATE AS Fecha,
        (ROW_NUMBER() OVER (ORDER BY serie.FechaHora) - 1)::INTEGER AS NumeroDia
    FROM periodo
    CROSS JOIN LATERAL generate_series(
        periodo.FechaInicio::TIMESTAMP,
        periodo.FechaFin::TIMESTAMP,
        INTERVAL '1 day'
    ) AS serie(FechaHora)
), valores_diarios AS (
    SELECT
        moneda.Id AS IdMoneda,
        fecha.Fecha,
        ROUND(
            (
                objetivo.ValorBase *
                (1 + objetivo.Variacion * SIN(
                    (fecha.NumeroDia + objetivo.Desfase)::DOUBLE PRECISION / 5.0
                ))
            )::NUMERIC,
            CASE WHEN objetivo.Sigla IN ('COP', 'BTC') THEN 2 ELSE 6 END
        )::DOUBLE PRECISION AS Cambio
    FROM monedas_objetivo AS objetivo
    INNER JOIN Moneda AS moneda
        ON moneda.Sigla = objetivo.Sigla
    CROSS JOIN fechas AS fecha
)
SELECT IdMoneda, Fecha, Cambio
FROM valores_diarios
ON CONFLICT (IdMoneda, Fecha)
DO UPDATE SET Cambio = EXCLUDED.Cambio;

COMMIT;

-- RESUMEN DE VERIFICACION: muestra las cuatro monedas incluso si alguna
-- faltara, y compara los dias registrados con los dias que debian generarse.
WITH monedas_objetivo AS (
    SELECT Sigla
    FROM (VALUES ('COP'), ('EUR'), ('GBP'), ('BTC')) AS datos(Sigla)
), periodo AS (
    SELECT
        (CURRENT_DATE - INTERVAL '2 months')::DATE AS FechaInicio,
        CURRENT_DATE::DATE AS FechaFin
)
SELECT
    objetivo.Sigla,
    moneda.Id AS IdMoneda,
    COUNT(cambio.Fecha) AS DiasRegistrados,
    (periodo.FechaFin - periodo.FechaInicio + 1) AS DiasEsperados,
    MIN(cambio.Fecha) AS PrimeraFecha,
    MAX(cambio.Fecha) AS UltimaFecha
FROM monedas_objetivo AS objetivo
CROSS JOIN periodo
LEFT JOIN Moneda AS moneda
    ON moneda.Sigla = objetivo.Sigla
LEFT JOIN CambioMoneda AS cambio
    ON cambio.IdMoneda = moneda.Id
   AND cambio.Fecha BETWEEN periodo.FechaInicio AND periodo.FechaFin
GROUP BY objetivo.Sigla, moneda.Id, periodo.FechaInicio, periodo.FechaFin
ORDER BY objetivo.Sigla;

-- FIN DEL ARCHIVO DML.

